  excerpt: "China's Spring Festival is one of Asia's most important celebrations — a season of color, family, and renewal.",
  content: `China's Spring Festival, also called Lunar New Year, is one of the most important traditional festivals in China and across Asia. It is celebrated not only in China but also in South Korea, Southeast Asia, Japan, and many neighboring regions.

The festivities span an extended period, beginning with the Laba Festival during the twelfth lunar month and concluding with the Lantern Festival on the fifteenth day of the first lunar month. Throughout this time, celebrations are notably colorful and vibrant, reflecting deep cultural traditions passed through generations.

It is a season of family reunions, new beginnings, and shared meals — one of the richest expressions of collective joy in the world.`
