window.BLOG_REGISTRY.push({
  id: "2015-03-01-chat-do-nothing-do-less",
  title: "Do Nothing, Do Less",
  author: "Sukee Parker",
  date: "2015-03-01",
  category: "Philosophy",
  tags: ["Mindfulness", "Tea"],
  excerpt: "Sometimes the best option is to do nothing. The more action we take, the more we move away from the natural process.",
  content: `Sometimes, the best option is to do nothing. The more action we take, the more we can move away from what would happen naturally. Observing, being present, and simply experiencing the moment — this is its own kind of doing.

Taking a break and doing nothing aligns with the spirit of tea time. Every day, spend a few minutes quieting your mind and stopping your actions. Just be in what you are in. You cannot keep running all the time. You have to rest.

Doing less can also produce better results. Unnecessary actions often lead to unintended consequences. Thinking before acting — and remembering that sometimes less is more — applies to speaking, doing, and thinking alike. Making things simple is a fundamental truth.

Sit. Drink your tea. Let that be enough.`
});
window.BLOG_REGISTRY.push({
  id: "2016-05-08-mothers-day",
  title: "Mother's Day",
  author: "Sukee Parker",
  date: "2016-05-08",
  category: "Lifestyle",
  tags: ["Holiday", "Family"],
  excerpt: "Observed on the second Sunday of May — a day to express appreciation for mothers through presence, flowers, and shared meals.",
  content: `Mother's Day originated in the United States in 1908 through Anna Jarvis's advocacy efforts. It is observed annually on the second Sunday of May and is centered on expressing appreciation for mothers through thoughtful presence, flowers, and shared time.

A gift idea worth considering: flower soap. Soap petals infused with subtle floral scents that can be scattered in bathwater for relaxation or displayed as bathroom décor — a small, genuinely useful indulgence that works as both a personal treat and a gift for someone you are visiting.

Another simple option: take your mother to brunch. A shared meal, unhurried, is often the best gift of all.`
});
window.BLOG_REGISTRY.push({
  id: "2016-05-15-steve-jobs-commencement-at-stanford-2005",
  title: "Steve Jobs Commencement at Stanford 2005",
  author: "Sukee Parker",
  date: "2016-05-15",
  category: "Philosophy",
  tags: ["Story", "Inspiration"],
  excerpt: "Three stories about connecting dots backward, finding work you love, and letting mortality clarify what matters.",
  content: `Steve Jobs delivered this commencement address at Stanford University on June 14, 2005. It has been cited widely ever since, and for good reason.

He organized it around three stories from his own life. The first is about trusting that the dots will connect — not in advance, but looking back. The second is about love and loss, and discovering that being fired from Apple eventually led him to the most creative period of his life. The third is about death as a clarifying force: when you know time is finite, it becomes easier to stop living someone else's life.

What stays with me: trusting in something so the dots can connect backward, looking for the work you actually love, and following your heart and intuition rather than letting other people's opinions drown them out.

The full transcript is worth reading in one sitting. Tea time is a good moment for it.`
});
window.BLOG_REGISTRY.push({
  id: "2016-07-10-review-how-to-do-grocery-shopping",
  title: "How to Do Grocery Shopping",
  author: "Sukee Parker",
  date: "2016-07-10",
  category: "Lifestyle",
  tags: ["Food", "Health", "Finance"],
  excerpt: "Grocery shopping can significantly impact your health, budget, and time — a few principles make it easier to get right.",
  content: `Grocery shopping is essential to daily life and one of the areas where small decisions compound quickly — in health, budget, and time.

**Shop the perimeter.** Fresh produce, dairy, and meats are typically located around the edges of the store. The center aisles are where the most processed items live.

**Label criteria.** Look for natural ingredients with minimal added sugars. Avoid artificial sweeteners, processed foods labeled "natural flavor," and oils like sunflower or canola. For olive oil, only extra virgin. For salt, Kosher salt with larger flakes and no additives. Avoid farm-raised shrimp and salmon from Southeast Asia; choose grass-fed meat.

**Shop seasonally.** Seasonal fruits and vegetables are fresher and generally more nutritious. What is in season varies by region — local farmers' market reports are a useful reference.

**Wash produce properly.** Soak in salt or vinegar-infused water for 10 minutes. Scrub firm items with a vegetable brush. Air-dry with cloth or paper towels. For heavily soiled produce, buying organic removes the concern entirely.

Small decisions at the grocery store, made consistently, shape what ends up in your body every day.`
});
window.BLOG_REGISTRY.push({
  id: "2016-08-21-chat-driving-safety",
  title: "Driving Safety",
  author: "Sukee Parker",
  date: "2016-08-21",
  category: "Lifestyle",
  tags: ["Safety"],
  excerpt: "Don't trust what you see when changing lanes — the vehicle you missed is the one that matters.",
  content: `More than once while driving, I have looked at the lane beside me, judged it clear, and begun to move — only to realize there was a vehicle I had not seen. The lane was not empty. I had simply missed something.

The habit that helps: when changing lanes, move one lane at a time. Never jump across two lanes at once. What is not immediately visible can appear quickly, and a slow methodical change gives you time to catch it.

Do not trust your first visual assessment. Check again. Then move.`
});
