window.BLOG_REGISTRY.push({
  id: "2018-03-18-story-the-balance-sheet",
  title: "The Balance Sheet",
  author: "Sukee Parker",
  date: "2018-03-18",
  category: "Lifestyle",
  tags: ["Story", "Finance"],
  excerpt: "A cautionary tale about what happens when you acquire a business without understanding what it owes.",
  content: `A balance sheet contains three essential elements: assets, liabilities, and equity. The fundamental accounting principle is that these must always balance.

A dry cleaning shop changed hands. The new owner was excited — the business seemed profitable, the price seemed fair. What they did not fully account for were the liabilities: hundreds of thousands of dollars in pre-sold gift cards issued by the previous owner. These were not revenue. They were future obligations — money customers had already paid for services not yet rendered. They belonged on the balance sheet as debt.

The previous owner had not disclosed them clearly. The new owner had not looked carefully enough.

The lesson: if you do not understand the business, find someone who does before you sign anything. If you proceed without that knowledge, the consequences are predictable. Hidden liabilities do not disappear when ownership changes — they transfer.

Due diligence is not a formality. It is the work.`
});
window.BLOG_REGISTRY.push({
  id: "2018-04-08-chat-how-much-do-you-know-about-wine",
  title: "How Much Do You Know About Wine?",
  author: "Sukee Parker",
  date: "2018-04-08",
  category: "Lifestyle",
  tags: ["Food", "Story"],
  excerpt: "Wine is a world of its own — and one of its most prominent figures turned out to be one of its greatest fraudsters.",
  content: `Wine is a significant industry with deeply devoted enthusiasts. Understanding even the basics can open up meaningful conversations with people who care about it.

One of the most striking figures in the wine world is Rudy Kurniawan, who was recognized between 2000 and 2013 for his extraordinary tasting expertise. His ability to identify vintages and estates was considered exceptional. Then, in 2013, he received a 10-year prison sentence for creating counterfeit wines and committing fraud on a large scale within the industry.

He was released on November 6, 2020, and subsequently deported to Indonesia. The documentary Sour Grapes chronicles his rise and fall — worth watching if you are curious about the intersection of connoisseurship, status, and deception.

The story is a reminder that expertise and authenticity are not always the same thing.`
});
window.BLOG_REGISTRY.push({
  id: "2018-04-22-data-monopolies",
  title: "Data Monopolies",
  author: "Sukee Parker",
  date: "2018-04-22",
  category: "Philosophy",
  tags: ["Technology", "Awareness"],
  excerpt: "A few technology companies now hold a concentration of power over information that has no historical precedent.",
  content: `Data monopolies were born in a digital world. They are dangerous because they erode individual freedom in ways that are difficult to see until the power is already entrenched.

An HBR article by Maurice E. Stucke — "Here Are All the Reasons It's a Bad Idea to Let a Few Tech Companies Monopolize Our Data" — makes the case clearly. Facing the tech giants, individuals are structurally vulnerable:

Twitter and YouTube can silence you by suspending your account. Google can shape what you find by controlling search results. Amazon can shift prices and product visibility without notice. Facebook can determine what information you see and what you do not.

How much unchecked power do these companies actually hold? The question is worth sitting with — not just as a political concern, but as a personal one about how we form opinions, make decisions, and understand the world.`
});
window.BLOG_REGISTRY.push({
  id: "2018-04-22-how-to-use-largest-wheat-theory-to-make-a-choice",
  title: "How to Use Largest Wheat Theory to Make a Choice",
  author: "Sukee Parker",
  date: "2018-04-22",
  category: "Philosophy",
  tags: ["Story", "Mindset"],
  excerpt: "Socrates gave three followers a wheat field and a single pass through it. The lesson was about how — and when — to decide.",
  content: `Socrates once instructed three followers to walk through a wheat field and retrieve the largest golden stalk they could find. Each was permitted only one pass through — no going back.

The first disciple moved quickly. After just a few steps, he picked what he thought was the largest stalk — only to see larger ones ahead. He finished with regret.

The second took the opposite approach. He always expected something better would appear further along, so he never picked anything at all. He reached the end empty-handed.

The third divided the field into thirds in his mind. In the first third, he observed the range — large, medium, and small. In the second third, he confirmed his observations. In the final third, he selected the largest stalk he could find based on what he had learned.

Life resembles this field. We walk through it only once, without the option to go back. The lesson is not about finding the best possible option — it is about developing enough judgment to recognize a very good one when it appears, and choosing it without waiting for something perfect that may never arrive.

The third approach — observe, confirm, then decide — is the one worth practicing.`
});
window.BLOG_REGISTRY.push({
  id: "2018-04-29-suspicious-old-friends",
  title: "Suspicious Old Friends",
  author: "Sukee Parker",
  date: "2018-04-29",
  category: "Philosophy",
  tags: ["Story", "Awareness"],
  excerpt: "Fraudsters are skilled at exploiting the one thing that makes us feel safe: the sense that someone is like us.",
  content: `Fraudsters are influence masters. They do not rely on force — they rely on the psychological shortcuts that guide our trust.

A friend visited a jade trading shop and was approached by a stranger who claimed to be from the same hometown. The person spoke the local dialect and demonstrated real familiarity with specific details. As the conversation deepened, the shop's selling agent began promoting expensive pieces — and the psychological groundwork had already been laid.

My friend grew suspicious and asked a targeted question about something specific to the hometown. The answer was wrong. The scheme unraveled.

The shop owner had built a systematic operation: staff trained to identify customers' origins, agents prepared to pose as hometown acquaintances for each region. The whole approach was built on the principle of liking — our natural tendency to trust people we perceive as similar to ourselves.

We are all susceptible to this. Similarity signals safety, and that is exactly what makes it exploitable. When warmth and familiarity appear unexpectedly, it is worth pausing to ask why they arrived when they did.`
});
window.BLOG_REGISTRY.push({
  id: "2018-05-06-how-much-can-a-psychological-suggestion-impact-us",
  title: "How Much Can a Psychological Suggestion Impact Us?",
  author: "Sukee Parker",
  date: "2018-05-06",
  category: "Philosophy",
  tags: ["Psychology", "Story"],
  excerpt: "The mind and body are more connected than we typically acknowledge — and belief alone can be enough to alter physical outcomes.",
  content: `A 1936 experiment, referenced by cardiologist Dr. Bernard Lown and psychology textbook author Dennis Coon, tested the outer limits of psychological suggestion.

A death row inmate was offered a choice between execution methods and selected death by blood loss. Researchers blindfolded him and told him that the water they had set nearby was actually his own blood draining from a wound. He could not verify this. He could only listen.

He died — despite no actual blood loss having occurred.

The account raises serious questions about the mind-body connection and how profoundly belief shapes physical reality. Related phenomena — placebo effects, psychosomatic illness, the mechanism sometimes called voodoo death — all point in the same direction: what we are convinced of, our body begins to enact.

This does not mean belief is everything. But it does mean the relationship between thought and physiology is far more direct than most of us treat it in daily life. What we tell ourselves about our circumstances, our health, and our future is not merely commentary. It participates in the outcome.`
});
