window.BLOG_REGISTRY.push({
  id: "2018-07-08-chat-live-like-a-cat",
  title: "Live Like a Cat",
  author: "Sukee Parker",
  date: "2018-07-08",
  category: "Philosophy",
  tags: ["Mindfulness", "Lifestyle"],
  excerpt: "A cat eats, plays, sleeps, and does only what brings it pleasure. Its single priority is its own wellbeing — and that is not selfishness, it is wisdom.",
  content: `Stéphane Garnier describes the feline philosophy in How to Think Like a Cat: eat, play, sleep, ensure comfort, and do only what brings pleasure. Wellbeing is the single priority.

Living like a cat means valuing your own wellness, concentrating on what genuinely matters, and releasing what does not serve you. Cats are independent — their choices come from internal preference, not external judgment. They do not rush. They do not act impulsively. They rest when tired, groom when needed, and maintain their own rhythm without apology.

Humans rush. We act before thinking. We carry things that no longer belong to us.

Adopt the cat as a role model: prioritize your wellbeing, do what brings you genuine pleasure, and let go of what does not. A stress-free existence requires intentionality — and cats have been practicing it longer than any productivity system.`
});
window.BLOG_REGISTRY.push({
  id: "2018-08-05-collection-indian-movies",
  title: "Indian Movies",
  author: "Sukee Parker",
  date: "2018-08-05",
  category: "Lifestyle",
  tags: ["Movies", "Culture"],
  excerpt: "Indian cinema splits broadly into two distinct traditions — spectacle and storytelling — and both are worth exploring.",
  content: `Indian cinema is one of the world's most prolific and culturally rich film traditions, divided broadly into two categories:

**Bollywood** is known for extravagant costumes, famous stars, beautiful faces, and elaborate song-and-dance sequences. It prioritizes entertainment and emotional spectacle.

**South Indian cinema** tends toward storytelling, realism, and social reflection — films that offer more food for thought on life and human experience.

Two films worth starting with:

**3 Idiots (2009, Bollywood)** — A comedy-drama about the pressures of India's educational system, balancing genuine entertainment with thought-provoking themes about ambition, friendship, and what education is actually for.

**Kaalapani (1996, South Indian)** — A portrait of India's freedom struggle against British colonial rule, set within the brutal conditions of the Cellular Jail. Demanding but deeply humanizing.

Both offer a window into Indian culture and history that is difficult to find elsewhere.`
});
window.BLOG_REGISTRY.push({
  id: "2018-08-12-chat-manners",
  title: "Manners",
  author: "Sukee Parker",
  date: "2018-08-12",
  category: "Philosophy",
  tags: ["Social", "Relationships"],
  excerpt: "Good manners are not a fixed set of rules — they are a skill of reading the room and responding to it well.",
  content: `Manners involve both behavior and thought, and they are highly contextual. What is appropriate depends on where you are, who you are with, and what is happening around you. Ethics help navigate these situations — what some call "reading the air" or "reading the room."

A few observations worth keeping:

**Chinese dinner customs.** At a Chinese dinner, parents cook to show love and children eat to express acceptance of it. When offered a second helping, saying yes is polite. Choosing a smaller piece signals respect and warmth.

**Show genuine interest.** Invite people to films, exhibitions, lunches, and events — not as a strategy but as a sincere gesture. Pay equal attention to everyone in a group rather than clustering around a few. When someone new joins a community, introducing them helps them feel seen and welcome.

**Thoughtful communication.** Choose carefully what to say and what to leave unsaid. When sharing a difficult truth, soften it by including your own experience or mistake alongside it. The message lands better and the relationship remains intact.

Etiquette ultimately comes down to reading the situation as accurately as you can and choosing your words, actions, and thoughts accordingly.`
});
window.BLOG_REGISTRY.push({
  id: "2018-10-28-chat-how-to-get-ahead-of-99-percent-of-it-project-managers",
  title: "How to Get Ahead of 99% of IT Project Managers",
  author: "Sukee Parker",
  date: "2018-10-28",
  category: "Productivity",
  tags: ["Career", "Productivity"],
  excerpt: "Seven habits that separate exceptional project managers from the majority — and a concrete action plan to build them.",
  content: `Standing out as a project manager requires more than technical competence. Seven habits make the difference:

**1. Establish the bigger picture from day one.**
Continuously communicate the project's broader context — the problem being solved, the solution, the timeline, and what success looks like. Keep the team aligned from start to finish.

**2. Practice self-reflection daily.**
Each day: review task prioritization and time allocation. Each week: assess project progress, upcoming needs, risks, team dynamics, and unresolved conflicts.

**3. Develop emotional intelligence.**
Know your own strengths and weaknesses. Build one-on-one relationships through careful listening. Understand what each team member needs and align individual goals with collective ones.

**4. Use data-driven tools.**
Make decisions with evidence and technology. Build credibility with stakeholders by demonstrating informed judgment. Stay current with emerging tools in your field.

**5. Ask questions proactively.**
Step back from the project regularly — take time to quiet your mind and look for issues that have not yet surfaced.

**6. Maintain discipline and documentation.**
Prioritize critical tasks. Document workflows, processes, ideas, meeting notes, and identified risks consistently.

**7. Avoid procrastination.**
Treat every task as its own project. Start immediately rather than waiting for the ideal moment.

**Practical rhythm:**
- Daily: one quiet hour for planning and reflection
- Weekly: status review covering risks and conflicts
- Monthly: full review of all active projects
- Before starting: two hours reviewing project materials
- With each team member: minimum 30-minute individual meetings
- After each project: one hour on lessons learned`
});
window.BLOG_REGISTRY.push({
  id: "2018-11-04-chat-are-you-a-lucky-person",
  title: "Are You a Lucky Person?",
  author: "Sukee Parker",
  date: "2018-11-04",
  category: "Philosophy",
  tags: ["Mindset", "Gratitude"],
  excerpt: "A hiring manager asks every candidate whether they feel lucky — and what they say reveals how they see the world.",
  content: `A hiring manager asks every candidate the same question: "Do you feel you are a lucky person?" Then they ask why.

The answer reveals something important — how a person relates to opportunity, to setback, and to the world in general. Someone who feels chronically unlucky tends to overlook the chances that pass in front of them. Strong desire and a clear sense of what you want directs attention toward the opportunities that already exist around you.

Frane Selak of Croatia survived multiple life-threatening accidents over decades — car crashes, a plane crash, a bus crash — and later won the lottery. Whether his life represents extraordinary good luck or extraordinary bad luck depends entirely on how you frame it.

That framing extends to ordinary setbacks too. Illness signals that something in your lifestyle needs to change. A rejected application points toward a different path. Mistakes and embarrassment build resilience. Job loss surfaces something about the role or the fit that was not working. None of these are purely negative — they are information.

The most useful perspective: feel grateful for being alive. Spread positivity. Pay attention to what you actually want. The people who feel lucky are often simply the people who notice more of what is already there.`
});
