window.BLOG_REGISTRY.push({
  id: "2020-11-22-miranda-right-from-the-shiromaru-kun-incident",
  title: "Miranda Right from the Shiromaru-Kun Incident",
  author: "Sukee Parker",
  date: "2020-11-22",
  category: "Philosophy",
  tags: ["Law", "Japan", "Story"],
  excerpt: "A 1984 missing child case in Hokkaido demonstrates how legal protections can shield suspects — and how one woman's right to silence prevented a conviction before the statute of limitations expired.",
  content: `The Shiromaru-Kun incident represents a significant missing children case in Hokkaido, Japan from November 1984. A 9-year-old boy named Shiromaru-Kun (城丸君), residing in Sapporo, vanished under mysterious circumstances near his residence.

A single mother present at the time, Kashouko (工藤加寿子), emerged as the primary suspect. However, insufficient evidence prevented case closure. Subsequently, a fire destroyed Kashouko's house, killing her husband, and child remains were discovered in the ruins. Despite repeated investigations, conviction remained impossible.

In November 1998 — fourteen years after the disappearance — advanced DNA technology confirmed the remains belonged to the missing child. Police classified it as murder, but prosecution faced an urgent deadline: Japan's 15-year indictment period was nearly expired.

During trial proceedings, the accused rejected approximately 400 prosecution questions with "I don't want to answer," effectively invoking the right to silence. This strategy prevented conviction. She subsequently received compensation for imprisonment and legal proceedings.

The incident sparked significant Japanese public controversy. Citizens believed she was guilty, yet the suspect successfully evaded conviction through strategic application of silence rights.

Japan subsequently reformed its Criminal Procedure Law, effective April 27, 2010, abolishing statutes of limitations for murder cases entirely — making them indefinite.

A difficult case that illuminates why legal protections exist, what happens when evidence is insufficient, and how law must balance individual rights against public expectations of justice.`
});
