window.BLOG_REGISTRY.push({
  id: "2021-07-25-chat-why-do-we-feel-jealous",
  title: "Why Do We Feel Jealous",
  author: "Sukee Parker",
  date: "2021-07-25",
  category: "Healthy",
  tags: ["Emotions", "Jealousy", "Self-awareness"],
  excerpt: "Jealousy stems from discontent with what we have and excessive desire for what we lack. Recognizing existing blessings can diminish it — but first we have to understand what it's telling us.",
  content: `Jealousy is a natural emotional response stemming from discontent with what we possess and excessive desire for what we lack.

From "101 Essays That Will Change the Way You Think": "The things you hate about others are the things you cannot see in yourself." Jealousy connects to insufficient self-confidence — it is often a mirror, not a complaint about someone else.

**Four strategies that help:**

1. **Practice appreciation**
Recognize existing blessings — good health, family safety, the resources you already have. Self-approval meditation can help shift attention from what's missing to what's present.

2. **Establish realistic goals**
Pursue concrete action rather than mere wishing. Jealousy thrives in the gap between wanting and doing. Movement closes that gap.

3. **Celebrate others' achievements**
Reframe others' success as a contribution to society rather than a subtraction from your share. Collaboration and competition are both choices.

4. **Recognize your own purpose**
Each life carries unique purpose and individual challenges worth appreciating. Someone else's success exists in a context you don't fully see.

Jealousy signals something we want but haven't pursued. That information is worth having — not the feeling itself, but what it points to.`
});
window.BLOG_REGISTRY.push({
  id: "2021-08-01-chat-minding-each-step",
  title: "Minding Each Step",
  author: "Sukee Parker",
  date: "2021-08-01",
  category: "Lifestyle",
  tags: ["Finance", "Mindfulness", "Habits"],
  excerpt: "My son had $1,000 from a summer internship and asked for approval on a $24 purchase. A classical proverb about rivers and trickles says everything.",
  content: `My son earned $1,000 from a summer internship. He came to me asking for approval on a $24 purchase of athletic shorts.

Despite already having plenty of shorts, he wanted more. I asked: does he truly need additional ones?

The question wasn't about $24. It was about the habit of minding each step.

A classical Chinese proverb: "A thousand journeys take every step. Without the accumulation of trickles, there will be no rivers and seas."

Mindfulness about minor financial decisions compounds over time. Each small choice shapes spending habits, which shape what we can afford, which shapes what becomes possible. The direction of a river is determined by each individual trickle, not just the major currents.

This isn't about being restrictive with small purchases. It's about the relationship between attention and outcome. People who mind small decisions tend to be the same people who have resources when large decisions arrive.

The $24 question was worth asking — not to deny the purchase, but to develop the habit of asking.`
});
