window.BLOG_REGISTRY.push({
  id: "2021-10-17-stay-true-to-yourself",
  title: "Stay True to Yourself",
  author: "Sukee Parker",
  date: "2021-10-17",
  category: "Philosophy",
  tags: ["Identity", "Self-acceptance", "Story"],
  excerpt: "\"We have to stay true to ourselves about who we are and where we belong.\" A story about a Chihuahua who pursued something outside his world — and the cost of that pursuit.",
  content: `"We have to stay true to ourselves about who we are and where we belong." — Sukee Parker

A small Chihuahua sought companionship with larger dog breeds rather than his own kind. After persistently pursuing a golden retriever in his neighborhood, he eventually confessed his feelings and made a bold romantic gesture.

The golden retriever responded violently, injuring the Chihuahua and causing permanent harm.

The story raises uncomfortable questions: Who bears responsibility — the retriever who acted according to its nature, or the Chihuahua who pursued something outside his world? Was this fate, a personal problem, or simply the consequence of misaligned expectations?

There is no clean answer. But the story points toward something real: when we pursue things that fundamentally don't fit — relationships, environments, identities that require us to be something we aren't — the friction has consequences.

This is not a call for limiting ambition. It's a call for honest self-knowledge. Knowing who you are and where you genuinely belong is not weakness — it is the foundation from which real growth becomes possible.`
});
window.BLOG_REGISTRY.push({
  id: "2021-11-07-paying-attention-to-the-details",
  title: "Paying Attention to the Details",
  author: "Sukee Parker",
  date: "2021-11-07",
  category: "Productivity",
  tags: ["Attention", "Security", "Mindfulness"],
  excerpt: "Nadia Boulanger: 'Anyone who acts without paying attention to what he is doing is wasting his life.' A cybersecurity example shows exactly what this costs.",
  content: `Composer Nadia Boulanger argued that "Anyone who acts without paying attention to what he is doing is wasting his life."

Mindfulness in daily tasks is essential to living a meaningful life — and, as a former FBI agent's cybersecurity example illustrates, sometimes essential to avoiding serious harm.

Scammers exploit human carelessness by sending fraudulent emails with subtle variations — changing one letter in a corporate email address. Email display settings that hide the actual address behind a display name make these deceptions harder to spot.

**What to do:**
- Disable display name settings that hide the actual sender email address
- Scrutinize unusual requests carefully, especially those involving money or credentials
- When an email request feels off — even slightly — verify through a separate channel before acting

The pattern is consistent across many types of fraud: fraudsters deliberately target our tendency toward inattention and complacency. Careless habits are vulnerabilities. Careful attention is protection.

The lesson applies beyond cybersecurity. Attention is how we catch the thing that would otherwise slip through — the typo, the wrong assumption, the detail that changes everything. The cost of not paying attention is rarely obvious until it's already paid.`
});
window.BLOG_REGISTRY.push({
  id: "2021-11-28-indian-history-in-movies",
  title: "Indian History in Movies",
  author: "Sukee Parker",
  date: "2021-11-28",
  category: "Lifestyle",
  tags: ["Movies", "India", "History"],
  excerpt: "Two films worth watching: 'Shakuntala Devi' (2020) about the human computer, and '83' (2021) about India's cricket world championship.",
  content: `Two Indian historical films worth tea-time discussion:

**Shakuntala Devi (2020)**
The film chronicles the life of the mathematical prodigy Shakuntala Devi (1929–2013), known as the "human computer." Born without formal mathematical training, she could perform complex calculations faster than electronic computers of her era.

Her story parallels that of another Indian math genius, Srinivasa Ramanujan (1887–1920), who also achieved extraordinary mathematical insight without conventional education. Both demonstrate that exceptional talent can emerge outside traditional academic structures.

**83 (2021) — Available on Netflix**
This film depicts the true story of India's cricket team winning the world championship on June 25, 1983, at Lord's Cricket Ground. The narrative captures both team struggles and national pride — a victory that no one expected from a country that had never won before.

Sports films work best when they're really about something else. "83" is about what happens when people believe something is possible before evidence suggests it should be. That's a story about more than cricket.

Both films use historical narrative to explore something about how extraordinary achievement happens — and what kind of people it requires.`
});
window.BLOG_REGISTRY.push({
  id: "2021-12-01-chat-read-a-book-every-week",
  title: "Read a Book Every Week",
  author: "Sukee Parker",
  date: "2021-12-01",
  category: "Books",
  tags: ["Reading", "Books", "Learning"],
  excerpt: "Rather than tracking how many books you read, read with a purpose — find a problem to address or a question to answer, then find books that help clear your doubts.",
  content: `Reading one book a week is an ambitious goal. Rather than focusing on conventional advice like reading 30 pages daily, a more effective approach starts differently.

Start with five books altogether and commit to them for one month. Different books require varying levels of engagement and pace — some deserve slow reading, others reward speed.

Read with purpose: "Find a problem to address or a question to answer. Then, read books that show us how to clear our doubts." This targeted approach makes the experience more engaging, whether focusing on a specific topic, exploring an author's complete works, or studying Nobel Prize winners.

Reading formats have evolved. Beyond traditional books, audiobooks and video summaries from channels like Productivity Game and Book Video Club make learning more flexible and enjoyable for different contexts — commutes, walks, chores.

Personal note: My goal is to read 1,000 books to broaden my perspective. As of December 2022, I had completed 120 books. The goal isn't the number — it's the accumulation of ideas and the expansion of what feels possible.`
});
window.BLOG_REGISTRY.push({
  id: "2021-12-05-learning-from-mistakes",
  title: "Learning from Mistakes",
  author: "Sukee Parker",
  date: "2021-12-05",
  category: "Philosophy",
  tags: ["Learning", "Wisdom", "Growth"],
  excerpt: "Sam Levenson: 'Learn from other people's mistakes. Life is too short to make them all yourself.' Five lessons worth internalizing.",
  content: `Sam Levenson: "Learn from other people's mistakes. Life is too short to make them all yourself."

There is wisdom in seeking guidance from those with more life experience — not as deference, but as efficiency. Some lessons are better borrowed than lived.

Five key lessons worth learning from others' experience:

**1. Prioritize Health**
Maintain physical wellness through regular activity, preventive medical care, and stress management. Health cannot be replaced. Other resources can be rebuilt — physical capacity often cannot.

**2. Stay Focused**
Concentrate on controllable elements — personal responses, values, effort — rather than external circumstances beyond your influence. Energy spent on what you cannot change is wasted.

**3. Listen First**
Emphasize understanding others through active listening and questioning before expressing your own thoughts. "Listening and understanding are more important than expressing what we think." Most people listen to respond, not to understand.

**4. Do Your Best**
Apply maximum effort without fixating on outcomes. Celebrate incremental progress and growth as valid markers of success. The outcome is only partially yours to control.

**5. Pursue Better Opportunities**
Continuously seek work that aligns with your capabilities and ambitions. Develop the necessary skills to get there. Staying where you've outgrown something is its own kind of mistake.

What lessons have you learned from others that saved you from learning them the hard way?`
});
window.BLOG_REGISTRY.push({
  id: "2021-12-19-chat-food-poisoning",
  title: "Food Poisoning",
  author: "Sukee Parker",
  date: "2021-12-19",
  category: "Healthy",
  tags: ["Health", "Food Safety", "Wellness"],
  excerpt: "A sudden onset of dizziness and disorientation — a reminder that what we eat shapes how we feel, and that food safety deserves more attention than we typically give it.",
  content: `A sudden onset of dizziness and disorientation. A friend nearby asked first: do you need emergency services? Then brought warm water to help.

Jim Rohn: "Take care of your body. It's the only place you have to live."

Food poisoning can arrive quickly and without warning. The causes are familiar — contaminated, spoiled, undercooked, or toxic foods — but easy to overlook in daily life when we move fast and eat carelessly.

**Common risks worth keeping in mind:**
- Foods left out of refrigeration too long
- Undercooked proteins (poultry, eggs, ground meat)
- Cross-contamination between raw and cooked foods
- Expired products consumed without checking
- Street food or buffets held at incorrect temperatures

Recovery from mild food poisoning usually involves rest, hydration, and time. More serious cases — severe vomiting, high fever, blood in stool — warrant medical attention.

The deeper reminder is simple: what we eat directly shapes how we feel, function, and think. Food safety is not an overcautious habit — it's basic care for the one body we get.`
});
