  excerpt: "International Museum Day is celebrated on May 18th each year. Since 1977, ICOM has recognized the museum community's contributions to cultural exchange and community enrichment.",
  content: `International Museum Day is celebrated on May 18th each year.

Since 1977, the International Council of Museums (ICOM) has celebrated this day annually to recognize the museum community's contributions to society and culture.

Museums serve important functions: they facilitate global cultural exchange, preserve the artifacts and stories that connect generations, and provide enrichment opportunities for communities of all sizes. Museums also play a vital role in fostering "peaceful coexistence" among diverse populations.

A tea-time suggestion: visit a local museum today, even briefly. Many offer free admission on International Museum Day. What's nearby that you've been meaning to see?

If travel isn't possible, many museums now offer virtual tours — a worthwhile way to spend a quiet tea-time afternoon.`
