window.BLOG_REGISTRY.push({
  "id": "2023-07-25-framework-thinking",
  "title": "Framework Thinking",
  "author": "Sukee Parker",
  "date": "2023-07-25",
  "category": "Productivity",
  "tags": [
    "Problem Solving"
  ],
  "excerpt": "Framework thinking enables us to respond swiftly, communicate effectively, and mitigate biases and errors.",
  "content": "<blockquote><span style=\"caret-color: rgb(42, 42, 42); color: rgb(42, 42, 42); font-family: Arial; font-size: 15px; font-style: italic; text-align: justify; background-color: rgb(248, 248, 248);\">‘Great Minds Think Alike” - An old saying</span><span style=\"caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: Arial; font-size: 18px; background-color: rgb(248, 248, 248);\"><br></span></blockquote><p><span>Humans possess a unique ability to think before acting, setting them apart from other species. However, there are instances when we require more time to deliberate, or when the issue is complex or misleading, potentially leading to biases or erroneous decisions. In such situations, we rely on thinking frameworks built upon the collective wisdom of our predecessors. These frameworks are essentially thinking systems constructed upon mental models.</span></p><p>These frameworks <b>serve as time-savers</b>, enabling us to swiftly analyze and assess situations, ultimately leading to informed decisions with deeper insights. They empower us to maintain control under high pressure, allowing us to <b>think clearly </b>and <b>communicate our thoughts logically and effectively</b>, especially in demanding situations. Moreover, these frameworks help <b>prevent errors and biases</b>. As the adage goes, “When all you have is a hammer, everything looks like a nail.” Our limited perspectives and biases can hinder our judgment. By employing a framework, we can transcend our usual boundaries, broaden our outlook, and approach problems with greater thoughtfulness, particularly when faced with intricate circumstances and challenging decisions.</p><p>During my MBA studies, I discovered that a significant portion of education involves acquiring various thinking frameworks, such as the 3C3P model for market analysis, Porter’s Five Forces and SWOT analysis for competition assessment, and value chain analysis for supplier evaluations.&nbsp;</p><p><span>Before we conclude, it’s important to recognize that merely knowing mathematical and physical formulas is insufficient to truly master a subject. As the saying goes, “Having a hammer doesn’t make you a carpenter.” To truly master framework thinking, we must consistently practice their applications in real-life scenarios and employ them flexibly to reap their benefits.</span></p>",
  "contentType": "html",
  "autoRead": true,
  "pinned": false
});
window.BLOG_REGISTRY.push({
  id: "2023-08-02-shakespeares-writing-and-steve-jobss-talking",
  title: "Shakespeare's Writing and Steve Jobs's Talking",
  author: "Sukee Parker",
  date: "2023-08-02",
  category: "Philosophy",
  tags: ["Excellence", "Depth", "Thinking"],
  excerpt: "Some individuals earn substantial income by attending meetings and speaking. But Shakespeare and Steve Jobs weren't 'merely' writing and speaking — their actions transcended surface-level activity.",
  content: `Some individuals earn substantial income simply by attending meetings and speaking daily. Why?

Shakespeare and Steve Jobs weren't "merely" writing and speaking. Their activities transcended the surface-level actions.

"Even though we do similar actions like reading, writing, and having meetings, the result will be different."

The danger is cargo cultism: copying the visible behaviors of successful people — the early mornings, the particular apps, the speech patterns — without understanding what actually generated the results.

What looks like "writing a play" from the outside was actually Shakespeare creating entire frameworks for understanding human psychology, constructing complex language structures, building unforgettable characters from universal archetypes. The action was writing. The work was something else entirely.

What looks like "giving a keynote" was Jobs synthesizing design philosophy, market understanding, and narrative structure into something that changed how people thought about technology. The action was speaking. The work was something else.

The principle: understand "the underlying principles, the outcome, and the process involved" in achievement rather than the surface actions. Look past what successful people visibly do to comprehend how and why they do it — the depth and intention behind the work.

Surface imitation produces surface results.`
});
window.BLOG_REGISTRY.push({
  id: "2023-08-06-losing-the-bigger-pictures",
  title: "Losing the Bigger Pictures",
  author: "Sukee Parker",
  date: "2023-08-06",
  category: "Healthy",
  tags: ["Health", "Holistic Thinking", "Systems"],
  excerpt: "A patient struggled with sleep issues, stomach discomfort, and high blood pressure. Multiple specialists, no resolution. Traditional Chinese medicine, treating the whole system, succeeded where symptom-focused approaches failed.",
  content: `A patient struggled with sleep issues, stomach discomfort, and high blood pressure. Multiple specialists were consulted — cardiologist, gastroenterologist, endocrinologist — but none could address the underlying interconnected problems.

"Treat the head when the head aches, treat the foot when the foot hurts" — this symptomatic approach addresses the part but misses the system.

Traditional Chinese medicine, which considers the entire body as an interconnected system, successfully treated the patient where fragmented specialist approaches had not.

The observation extends beyond medicine:

**In academia:** Compartmentalized fields limit problem-solving capacity. The most interesting problems exist at the intersections between disciplines — where none of the specialists feel at home.

**In business:** Cross-departmental collaboration between development, marketing, sales, and operations teams is essential. When each department optimizes for its own metrics without understanding the whole, the system underperforms even when each part performs.

**In decision-making:** Incremental minor decisions can accumulate into significant negative outcomes — a principle related to the slippery slope. Maintaining long-term perspective is essential even when each individual choice seems small.

The bigger picture is not always visible from inside the specialized view. Sometimes you have to step back to see what the parts are doing to the whole.`
});
window.BLOG_REGISTRY.push({
  id: "2023-08-07-the-cost-of-being-different",
  title: "The Cost of Being Different",
  author: "Sukee Parker",
  date: "2023-08-07",
  category: "Philosophy",
  tags: ["Conformity", "Choice", "Individuality"],
  excerpt: "When hail damage prompted most neighbors to replace roofs with standard shingles, one chose a distinctive metal roof. Stunning — but it required lightning rods. 'There is a price to be different.'",
  content: `When hail damage prompted most residents in a neighborhood to replace roofs with standard shingles, one neighbor chose a distinctive metal roof instead.

The metal roof was "stunning" and visually striking — clearly different, clearly beautiful.

But the choice came with an unexpected consequence: increased lightning risk, requiring the installation of lightning rods that the standard-shingle neighbors didn't need.

"There is a price to be different."

This is not an argument for conformity. The metal roof may be worth the lightning rods. Many nonconforming choices are worth their costs.

But the story illustrates something real: when you deviate from the standard path, you accept the standard path's risks plus the new risks that come with your alternative. The costs aren't always obvious in advance. They reveal themselves after the choice is made.

The question before choosing something different is not just "is this better?" but "what are the hidden costs of this deviation?" The person who chooses the metal roof and also installs the lightning rods has made a complete decision. The person who only chose the roof has made a partial one.

Differentiation is available to everyone. Full accounting for its consequences is the harder part.`
});
window.BLOG_REGISTRY.push({
  "id": "2023-08-09-circle-of-competence-why-everyone-needs-to-know-the-concept",
  "title": "Circle of Competence: Why Everyone Needs to Understand This Concept",
  "author": "Sukee Parker",
  "date": "2023-08-09",
  "category": "Philosophy",
  "tags": [
    "Self-Awareness",
    "Decision Making",
    "Learning"
  ],
  "excerpt": "The real danger isn't what you don't know — it's what you think you know but actually don't. The gap between perceived and actual competence is where overconfidence lives.",
  "content": "<p><img src=\"blogs/images/2023-08-09-circle-of-competence-why-everyone-needs-to-know-the-concept_img1.jpg\"></p><p></p><p></p><p>Believe it or not, <b>we all operate within our circle of competence</b>, which defines three situations of problem-solving: within our genuine expertise,&nbsp;<span>&nbsp;within what we think we know but outside of what we actually know, and</span><span>&nbsp;outside our known competence.&nbsp;</span></p>\n<p>When operating within our genuine expertise, we shouldn’t pose problems because we know what to do. When an issue arises that we know we don’t know, we naturally prompt appropriate caution to avoid the risk. So it is also not an issue. However, the area&nbsp;<b>between when we believe we know but actually don’t is <font color=\"#e91e63\">a danger zone</font>.&nbsp; </b>In such situations, we could be <b>unrealistic in our confidence and take risks we can’t handle</b>. There’s also a famous Murphy’s Law: “Anything that can go wrong will go wrong.” As a result, problems arise.</p>\n<p>When we know the circle of competence concept, we can be more conscious&nbsp; of self-awareness. We have to <b>know our boundaries between our actual knowledge and the perceived expertise.</b> A pertinent question to ask regularly is: “<b>Am I operating within my genuine area of competence, or within the imaginary boundaries I’ve set for myself?”&nbsp;</b><span>To bridge this gap, we need to stay humble and accept our ignorance. Two approaches can help us:</span></p>\n<p></p><ul><li><span>Continuous education: Learning frameworks and studying the domain deeply. Now you can ask AI \"Provide me complete picture on the topic.\" or \"What are my blind spot on this topic.\".&nbsp;</span></li><li><span>Seeking diverse perspectives: Engaging in discussions and dialogues to expose blind spots more effectively than solitary study. Ask AI, like \"Please tell me perspectives from all kinds of possible stakeholders in this situation.\"</span></li></ul><p></p>\n<p>The circle of competence also teaches us to plan well for our communications. <b>We have to communicate based on others’ competence.</b> If we explain beyond their knowledge, they will have trouble comprehending us. We can find ourselves speaking to deaf ears. This is a cognitive limitation.&nbsp;</p>",
  "contentType": "html",
  "autoRead": true,
  "pinned": false
});
window.BLOG_REGISTRY.push({
  id: "2023-08-10-comparing-note-taking-applications",
  title: "Comparing Note Taking Applications",
  author: "Sukee Parker",
  date: "2023-08-10",
  category: "Productivity",
  tags: ["Notion", "Evernote", "Productivity"],
  excerpt: "Four note-taking tools, each with a distinct purpose: Apple Notes for quick capture, Quip for work collaboration, Evernote for personal documents, and Notion for project planning.",
  content: `A practical note-taking system using four tools, each serving a distinct purpose:

**Apple Notes** — Quick and temporary notes
For saved reading, to-do lists, and quick reference for offline access. The fastest way to capture something before it disappears. Syncs across Apple devices instantly.

**Quip** — Work collaboration
Used at work for "content collaboration, project documents, and reports." Particularly useful when content needs to be co-authored or reviewed by colleagues.

**Evernote** — Personal documents and contacts
Stores personal reference documents and contact information. The long-term repository for things that need to be found again years later.

**Notion** — Project planning
Manages project planning with task management capabilities. Database features enable more structured organization than flat notes allow.

**The workflow:**
Regularly review Apple Notes and transfer relevant items to Evernote. This prevents accumulation without curation.

Apply the **4Rs method** (from the 5Rs note-taking framework) to distill and organize the Evernote collection: Reduce, Recite, Reflect, and Review. This ensures information remains systematized and actually accessible — not just stored.

The tool choice matters less than the system. A consistent review and transfer workflow turns captured notes into usable knowledge.`
});
