  excerpt: "A sales candidate asked to sell a rotten apple reframed it as 'an aged, antique apple.' Despite concerns about honesty, that candidate became the best salesperson the hiring manager ever employed.",
  content: `A hiring manager and colleague asked sales candidates to sell a rotten apple. One memorable response reframed the product entirely:

"This may look like a rotten apple, but it's actually an aged, antique apple. They say an apple a day keeps the doctor away, and the longer they age, the more nutrients they gain!" — a job candidate

Despite initial concerns about honesty, this particular candidate ultimately became the best salesperson the hiring manager ever employed.

The story comes from "The Hidden Potential."

The lesson isn't about dishonesty — it's about creative reframing. The candidate didn't lie about the apple being rotten. They found a perspective that was both true and persuasive. That capacity for reframing under pressure is exactly what sales requires.

What looks like evasion in an interview answer is sometimes exactly the skill the role demands.`
