window.BLOG_REGISTRY.push({
  id: "2025-11-02-chat-hey-thats-snake-oil",
  title: "Hey, That's Snake Oil!",
  author: "Sukee Parker",
  date: "2025-11-02",
  category: "Chat",
  tags: ["History", "Skepticism", "AI", "Critical Thinking"],
  excerpt: "Chinese railroad workers introduced genuine snake oil in the 1800s — derived from Chinese water snakes, rich in Omega-3s. Counterfeiters destroyed its credibility. 'Snake oil salesman' entered the lexicon.",
  content: `The origins of "snake oil" as meaning "a fraudulent remedy or scam":

In the mid-1800s, Chinese railroad workers introduced authentic snake oil derived from Chinese water snakes, which contained beneficial Omega-3 fatty acids for joint and muscle pain relief. The original remedy was legitimate.

Unscrupulous salesmen capitalized on its popularity by creating counterfeit versions using "alcohol, turpentine, and spices" while making false curative claims.

A pivotal moment in 1917: U.S. authorities tested Clark Stanley's Snake Oil Liniment and discovered it contained no actual snake oil.

This investigation transformed "snake oil salesman" into a lasting idiom for deception and empty promises. The irony: the imitations destroyed the credibility of the original genuine product.

Inspired by "AI Snake Oil: What Artificial Intelligence Can Do, What It Can't, and How to Tell the Difference" — the same dynamic applies to AI claims today.`
});
window.BLOG_REGISTRY.push({
  id: "2025-11-02-chat-how-to-prevent-locusts-swarm",
  title: "How to Prevent Locusts Swarm?",
  author: "Sukee Parker",
  date: "2025-11-02",
  category: "Chat",
  tags: ["Nature", "Locusts", "Biology", "Systems Thinking"],
  excerpt: "Locust behavior transforms dramatically as population density increases — physical contact triggers serotonin release, converting solitary insects into coordinated migratory swarms. Key prevention: monitoring the gathering.",
  content: `Individual locusts typically remain solitary. But when density reaches approximately 10-15 per square meter, "physical contact between locust triggers the release of serotonin, which alters their nervous systems, behaviors, and even their coloration."

This transformation — phase polyphenism — converts isolated insects into highly coordinated migratory swarms.

**Historical scale:** The 1875 Rocky Mountain locust swarm covered roughly 198,000 square miles across North America, containing 12.5 trillion locusts and destroying nearly three-fourths of U.S. crop production that year.

**Key prevention strategy:** "Monitoring the gathering" — tracking hatching patterns to prevent sudden large-scale transformations before they occur.

The lesson extends beyond entomology: many dangerous phenomena begin as small, manageable patterns. Early detection — before the threshold is crossed — is far cheaper than response after transformation.

Source: Brian Klaas's 2024 book *Fluke: Chance, Chaos, and Why Everything We Do Matters*.`
});
